std::set<int> s = {10, 20, 30, 40};

// Finds the first element >= target value.
// O(log N) time complexity (BST traversal).

// Case 1: Value not present
std::set<int>::iterator it1 = s.lower_bound(25);
// *it1 == 30

// Case 2: Value present
auto it2 = s.lower_bound(20);
// *it2 == 20

// Case 3: Value > max element
auto it3 = s.lower_bound(50);
// it3 == s.end()

// Returns std::set::const_iterator if set is const.
// Uses the set's internal comparison object (std::less by default).
